    if ($diff->y > 0) return $diff->y . ' г. назад';
    if ($diff->m > 0) return $diff->m . ' мес. назад';
    if ($diff->d > 0) return $diff->d . ' дн. назад';
    if ($diff->h > 0) return $diff->h . ' ч. назад';
    if ($diff->i > 0) return $diff->i . ' мин. назад';
    return 'только что';
}

